async function yalcaSignUp(e,a,r,n){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente. Veja o guia de configuração."};const{data:s,error:t}=await supabaseClient.auth.signUp({email:e.trim(),password:a,options:n?{captchaToken:n}:void 0});if(t)return{ok:!1,error:yalcaAuthErrorMessage(t)};if(!s.session)return{ok:!0,pendingEmailConfirmation:!0};const{error:o}=await supabaseClient.from("client_profiles").insert({email:e.trim(),store_name:r||""});return o?{ok:!1,error:"Conta criada, mas houve um erro ao registrar seu perfil: "+o.message}:{ok:!0,pendingEmailConfirmation:!1}}async function yalcaLogin(e,a,r){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente. Veja o guia de configuração."};const{data:n,error:s}=await supabaseClient.auth.signInWithPassword({email:e.trim(),password:a,options:r?{captchaToken:r}:void 0});return s?{ok:!1,error:yalcaAuthErrorMessage(s),code:yalcaAuthErrorCode(s)}:{ok:!0,session:n.session}}async function yalcaResendConfirmation(e){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente."};const{error:a}=await supabaseClient.auth.resend({type:"signup",email:e.trim()});return a?{ok:!1,error:yalcaAuthErrorMessage(a)}:{ok:!0}}async function yalcaRequestPasswordReset(e,a){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente."};const r=`${window.location.origin}${window.location.pathname.replace(/login\.html$/,"")}reset-password.html`,{error:n}=await supabaseClient.auth.resetPasswordForEmail(e.trim(),{redirectTo:r,captchaToken:a});return n?{ok:!1,error:yalcaAuthErrorMessage(n)}:{ok:!0}}async function yalcaUpdatePassword(e){if(!supabaseClient)return{ok:!1,error:"Configuração do Supabase pendente."};const{error:a}=await supabaseClient.auth.updateUser({password:e});return a?{ok:!1,error:yalcaAuthErrorMessage(a)}:{ok:!0}}async function yalcaIsLoggedIn(){if(!supabaseClient)return!1;const{data:e}=await supabaseClient.auth.getSession();return!!e.session}async function yalcaCurrentUser(){if(!supabaseClient)return null;const{data:e}=await supabaseClient.auth.getUser();return e.user||null}async function yalcaLogout(){supabaseClient&&await supabaseClient.auth.signOut()}async function yalcaRequireAuth(){return!!await yalcaIsLoggedIn()||(window.location.href="login.html",!1)}async function yalcaGetOwnProfile(){const e=await yalcaCurrentUser();if(!e)return null;const{data:a,error:r}=await supabaseClient.from("client_profiles").select("*").eq("user_id",e.id).maybeSingle();if(r)throw new Error(r.message);return a}async function yalcaIsAdmin(){const e=await yalcaCurrentUser();if(!e)return!1;const{data:a,error:r}=await supabaseClient.from("admins").select("user_id").eq("user_id",e.id).maybeSingle();return!r&&!!a}function yalcaAuthErrorMessage(e){const a=e&&e.message?e.message:"";return a.includes("Invalid login credentials")?"E-mail ou senha incorretos.":a.includes("Email not confirmed")?"Este e-mail ainda não foi confirmado. Verifique sua caixa de entrada.":a.includes("User already registered")?"Já existe uma conta com este e-mail. Tente entrar em vez de criar uma nova conta.":a.includes("Password should be at least")?"A senha precisa ter pelo menos 6 caracteres.":a.includes("captcha")?"Não foi possível validar a verificação de segurança. Tente novamente.":a.includes("rate limit")||a.includes("Too many requests")?"Muitas tentativas em pouco tempo. Aguarde alguns minutos e tente novamente.":a||"Não foi possível concluir. Tente novamente em instantes."}function yalcaAuthErrorCode(e){const a=e&&e.message?e.message:"";return a.includes("Email not confirmed")?"email_not_confirmed":a.includes("Invalid login credentials")?"invalid_credentials":null}